"},{"path":"src/main/java/com/example/shortener/service/UrlValidator.java","content":"package com.example.shortener.service;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {

    private static final String MESSAGE = "url must be an absolute http or https URL";

    public void validate(String url) {
        if (url == null || url.isBlank()) {
            throw new InvalidUrlException(MESSAGE);
        }
        URI uri;
        try {
            uri = new URI(url);
        } catch (URISyntaxException e) {
            throw new InvalidUrlException(MESSAGE);
        }
        if (!uri.isAbsolute()) {
            throw new InvalidUrlException(MESSAGE);
        }
        String scheme = uri.getScheme().toLowerCase(Locale.ROOT);
        if (!scheme.equals("http") && !scheme.equals("https")) {
            throw new InvalidUrlException(MESSAGE);
        }
        String host = uri.getHost();
        if (host == null || host.isEmpty()) {
            throw new InvalidUrlException(MESSAGE);
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/service/ShortCodeGenerator.java","content":"package com.example.shortener.service;

import java.security.SecureRandom;
import org.springframework.stereotype.Component;

@Component
public class ShortCodeGenerator {

    static final String ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    static final int LENGTH = 7;

    private final SecureRandom random = new SecureRandom();

    public String generate() {
        StringBuilder sb = new StringBuilder(LENGTH);
        for (int i = 0; i < LENGTH; i++) {
            sb.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));
        }
        return sb.toString();
    }
}
"},{"path":"src/test/java/com/example/shortener/service/UrlValidatorTest.java","content":"package com.example.shortener.service;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class UrlValidatorTest {

    private final UrlValidator validator = new UrlValidator();

    @ParameterizedTest
    @ValueSource(strings = {"http://example.com", "https://example.com/a/b?x=1", "HTTPS://Example.com", "http://localhost:8080/x"})
    void acceptsValid(String url) {
        assertDoesNotThrow(() -> validator.validate(url));
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "   ", "/relative/path", "example.com", "ftp://example.com", "javascript:alert(1)", "http://", "http:///path", "http://exa mple.com", "mailto:a@b.com"})
    void rejectsInvalid(String url) {
        assertThrows(InvalidUrlException.class, () -> validator.validate(url));
    }

    @Test
    void rejectsNull() {
        assertThrows(InvalidUrlException.class, () -> validator.validate(null));
    }
}
"},{"path":"src/test/java/com/example/shortener/service/ShortCodeGeneratorTest.java","content":"package com.example.shortener.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.HashSet;
import java.util.Set;
import org.junit.jupiter.api.Test;

class ShortCodeGeneratorTest {

    private final ShortCodeGenerator generator = new ShortCodeGenerator();

    @Test
    void generatesSevenBase62Chars() {
        for (int i = 0; i < 200; i++) {
            String code = generator.generate();
            assertEquals(7, code.length());
            assertTrue(code.matches("[A-Za-z0-9]{7}"));
        }
    }

    @Test
    void codesVary() {
        Set<String> codes = new HashSet<>();
        for (int i = 0; i < 100; i++) {
            codes.add(generator.generate());
        }
        assertTrue(codes.size() > 90);
    }
}
"}],"notes":"Validator is a Spring component exposing validate(String); LinkNotFoundException carries the code with the design's detail message. Tests use JUnit params (included in spring-boot-starter-test)."}

